+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+const crypto = require('node:crypto');
+const { spawnSync } = require('node:child_process');
+
+const backend = path.resolve(__dirname, '..');
+process.loadEnvFile(path.join(backend, '.env'));
+const { PrismaClient } = require(path.join(backend, 'node_modules/@prisma/client'));
+const client = new PrismaClient();
+const migrationName = '20261110100424_';
+const databaseName = `prisma_recovery_${crypto.randomBytes(8).toString('hex')}`;
+const temporaryDirectory = fs.mkdtempSync(path.join(os.tmpdir(), 'prisma-recovery-'));
+let databaseCreated = false;
+const checksum = (content) => crypto.createHash('sha256').update(content).digest('hex');
+
+async function main() {
+  const history = await client.$queryRawUnsafe('SELECT migration_name, checksum FROM _prisma_migrations WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL ORDER BY started_at');
+  const missing = history.find((row) => row.migration_name === migrationName);
+  if (!missing) throw new Error('The expected applied migration was not found.');
+  const migrations = path.join(backend, 'prisma/migrations');
+  const knownDirectory = path.join(temporaryDirectory, 'migrations');
+  fs.mkdirSync(knownDirectory);
+  fs.copyFileSync(path.join(migrations, 'migration_lock.toml'), path.join(knownDirectory, 'migration_lock.toml'));
+  for (const row of history.filter((row) => row.migration_name !== migrationName)) {
+    const source = path.join(migrations, row.migration_name, 'migration.sql');
+    const content = fs.readFileSync(source);
+    if (checksum(content) !== row.checksum) throw new Error(`Checksum mismatch in ${row.migration_name}`);
+    const destination = path.join(knownDirectory, row.migration_name);
+    fs.mkdirSync(destination);
+    fs.writeFileSync(path.join(destination, 'migration.sql'), content);
+  }
+  await client.$executeRawUnsafe(`CREATE DATABASE "${databaseName}"`);
+  databaseCreated = true;
+  const shadowUrl = new URL(process.env.DATABASE_URL);
+  shadowUrl.pathname = `/${databaseName}`;
+  const result = spawnSync(process.execPath, [
+    path.join(backend, 'node_modules/prisma/build/index.js'), 'migrate', 'diff',
+    '--from-migrations', knownDirectory,
+    '--to-schema-datamodel', path.join(backend, 'prisma/schema.prisma'),
+    '--shadow-database-url', shadowUrl.toString(), '--script',
+  ], { cwd: backend, encoding: 'utf8', timeout: 60000 });
+  if (result.status !== 0) {
+    console.error((result.stderr || 'Schema reconstruction failed.').replace(/postgres(?:ql)?:\/\/[^\s]+/g, '<REDACTED>'));
+    throw new Error('The migration diff failed.');
+  }
+  const sql = result.stdout.replace(/\r\n/g, '\n');
+  console.log('Reconstructed SQL:\n' + sql);
+  const bodies = [sql, sql.trimEnd(), sql.trimEnd() + '\n', sql.trimEnd() + '\n\n'];
+  const candidates = bodies.flatMap((body) => [body, body.replace(/\n/g, '\r\n')]);
