+  if (exact === undefined) throw new Error('Reconstructed SQL did not match the recorded checksum; no migration file was written.');
+  fs.writeFileSync(path.join(migrations, migrationName, 'migration.sql'), exact, { flag: 'wx' });
+  console.log(`Restored ${migrationName}/migration.sql with exact checksum ${missing.checksum}`);
+}
+
+main().catch((error) => {
+  console.error(error.code || error.message.replace(/postgres(?:ql)?:\/\/[^\s]+/g, '<REDACTED>'));
+  process.exitCode = 1;
+}).finally(async () => {
+  try {
+    if (databaseCreated) {
+      if (!/^prisma_recovery_[a-f0-9]{16}$/.test(databaseName)) throw new Error('Unexpected temporary database name.');
+      await client.$executeRawUnsafe(`DROP DATABASE "${databaseName}"`);
+      console.log('Temporary recovery database removed.');
+    }
+  } finally {
+    await client.$disconnect();
+    for (const directory of fs.readdirSync(path.join(temporaryDirectory, 'migrations'), { withFileTypes: true })) {
+      const destination = path.join(temporaryDirectory, 'migrations', directory.name);
+      if (directory.isDirectory()) {
+        fs.unlinkSync(path.join(destination, 'migration.sql'));
+        fs.rmdirSync(destination);
+      } else {
+        fs.unlinkSync(destination);
+      }
+    }
+    fs.rmdirSync(path.join(temporaryDirectory, 'migrations'));
+    fs.rmdirSync(temporaryDirectory);
+  }
+});
