@Injectable()
export class ExecutionStreamService {
  constructor(
    private readonly queryBus: QueryBus,
    private readonly eventPublisher: ExecutionEventPublisher,
    private readonly access: SessionAccessPort,
  ) {}

  createStream(executionId: string, userId: string, sessionVersion?: number): Observable<MessageEvent> {
    return new Observable<MessageEvent>((subscriber) => {
      let cleanedUp = false;
      let unsubscribe: () => void = () => undefined;
      let heartbeat: NodeJS.Timeout | undefined;

      const doCleanup = () => {
        if (cleanedUp) return;
        cleanedUp = true;
        unsubscribe();
        if (heartbeat) clearInterval(heartbeat);
      };

      void (async () => {
        try {
          if (!await this.access.isCurrent(userId, sessionVersion)) { subscriber.complete(); doCleanup(); return; }
          const snapshot: unknown = await this.queryBus.execute(
            new GetExecutionQuery(executionId, userId),
          );

          if (cleanedUp || subscriber.closed) return;

          subscriber.next({
            type: 'execution.snapshot',
            data: {
              event: 'execution.snapshot',
              executionId,
              payload: snapshot,
              ts: new Date().toISOString(),
            },
          });

          if (
            snapshot &&
            typeof snapshot === 'object' &&
            'status' in snapshot &&
            isTerminalExecutionState('execution.snapshot', snapshot.status)
          ) {
            subscriber.complete();
            doCleanup();
            return;
          }

          unsubscribe = this.eventPublisher.subscribe(executionId, (event) => {
            void (async () => {
            if (!await this.access.isCurrent(userId, sessionVersion)) { subscriber.complete(); doCleanup(); return; }
            if (cleanedUp || subscriber.closed) return;
            subscriber.next({
              type: event.event,
              data: event,
            });

            if (isTerminalExecutionState(event.event, event.status)) {
              subscriber.complete();
              doCleanup();
            }
            })().catch(() => { subscriber.complete(); doCleanup(); });
          });

          heartbeat = setInterval(() => { void (async () => {
            if (!await this.access.isCurrent(userId, sessionVersion)) { subscriber.complete(); doCleanup(); return; }
            if (!cleanedUp && !subscriber.closed) {
              subscriber.next({
                type: 'heartbeat',
                data: { ts: new Date().toISOString() },
              });
            }
          })().catch(() => { subscriber.complete(); doCleanup(); }); }, 15000);
        } catch (error) {
          subscriber.error(error);
          doCleanup();
        }
      })();

      return () => {
        doCleanup();
      };
    });
  }
}
