  async claimQueuedExecution(id: string, startedAt: Date): Promise<boolean> {
    return this.prisma.$transaction(async (tx) => {
      const owners = await tx.$queryRaw<{ is_active: boolean }[]>`SELECT u.is_active FROM users u JOIN workflows w ON w.owner_id = u.id JOIN executions e ON e.workflow_id = w.id WHERE e.id = ${id}::uuid FOR UPDATE OF u`;
      if (!owners[0]) return false;
      if (!owners[0].is_active) {
        await tx.execution.updateMany({ where: { id, status: ExecutionStatus.QUEUED }, data: { status: ExecutionStatus.CANCELLED, cancellationReason: 'OWNER_SUSPENDED', finishedAt: startedAt } });
        return false;
      }
      const { count } = await tx.execution.updateMany({ where: { id, status: ExecutionStatus.QUEUED }, data: { status: ExecutionStatus.RUNNING, startedAt } });
      return count === 1;
    });
  }

  async failUnfinishedExecution(id: string, finishedAt: Date): Promise<void> {
    await this.prisma.execution.updateMany({
      where: {
        id,
        status: { in: [ExecutionStatus.QUEUED, ExecutionStatus.RUNNING] },
