  async failStaleExecutions(startedBefore: Date): Promise<number> {
    const { count } = await this.prisma.execution.updateMany({
      where: {
        status: ExecutionStatus.RUNNING,
        triggerType: TriggerType.MANUAL,
        startedAt: { lt: startedBefore },
