      },
      select: { id: true },
      });
    });
    return row.id;
  }

  async findExecutionByIdempotencyKey(
    actorId: string,
    idempotencyKey: string,
  ): Promise<ExecutionStartRecord | null> {
    const row = await this.prisma.execution.findFirst({
      where: { triggeredById: actorId, idempotencyKey },
      select: {
        id: true,
        workflowId: true,
        workflowVersionId: true,
        triggerType: true,
        status: true,
        queuedAt: true,
        startedAt: true,
      },
    });
    if (!row) return null;
    return {
      ...row,
      triggerType: row.triggerType as TriggerType,
      status: row.status as ExecutionStatus,
    };
  }

  async resolveCredential(
    credentialId: string,
    ownerId: string,
  ): Promise<ResolvedCredential> {
    const credential = await this.prisma.connectorCredential.findUnique({
      where: { id: credentialId },
      include: { connector: true },
    });
    if (!credential) {
      throw new Error('credential was not found');
    }
    if (credential.ownerId !== ownerId) {
      throw new Error('credential does not belong to this workflow owner');
    }

    const encryptionKey = process.env['ENCRYPTION_KEY'];
    if (!encryptionKey) {
      throw new Error('Credential decryption key is not configured');
    }

    const plaintext = EncryptionUtil.decrypt(
      credential.encryptedSecret,
      encryptionKey,
    );
    return {
      connectorKey: credential.connector.key,
      secret: <REDACTED> as unknown,
    };
  }

  async saveNodeLog(executionId: string, log: NodeLogRecord): Promise<void> {
    const data = {
      nodeKey: log.nodeKey,
      status: log.status,
      input: jsonValue(log.input),
      output: jsonValue(log.output),
      errorMessage: log.errorMessage,
      errorCode: log.status === ExecutionStatus.FAILED ? (log.errorCode ?? 'NODE_EXECUTION_FAILED') : null,
      startedAt: log.startedAt,
      finishedAt: log.finishedAt,
      durationMs: log.finishedAt
        ? log.finishedAt.getTime() - log.startedAt.getTime()
        : null,
    };

    try {
      await this.prisma.executionNodeLog.upsert({
        where: { executionId_nodeId: { executionId, nodeId: log.nodeId } },
        create: { executionId, nodeId: log.nodeId, ...data },
        update: data,
      });
    } catch {
      // Fallback if the database has not yet applied the unique constraint migration (Postgres 42P10)
      const existing = await this.prisma.executionNodeLog.findFirst({
        where: { executionId, nodeId: log.nodeId },
        select: { id: true },
      });

      if (existing) {
        await this.prisma.executionNodeLog.update({
          where: { id: existing.id },
          data,
        });
      } else {
        await this.prisma.executionNodeLog.create({
          data: { executionId, nodeId: log.nodeId, ...data },
        });
      }
    }
  }

  async finishExecution(
    id: string,
    status: ExecutionStatus,
    finishedAt: Date,
    durationMs: number,
  ): Promise<void> {
    await this.prisma.execution.update({
      where: { id },
      data: { status: status, finishedAt, durationMs, errorCode: status === ExecutionStatus.FAILED ? 'WORKFLOW_EXECUTION_FAILED' : null },
    });
  }

  async claimQueuedExecution(id: string, startedAt: Date): Promise<boolean> {
    return this.prisma.$transaction(async (tx) => {
      const owners = await tx.$queryRaw<{ is_active: boolean }[]>`SELECT u.is_active FROM users u JOIN workflows w ON w.owner_id = u.id JOIN executions e ON e.workflow_id = w.id WHERE e.id = ${id}::uuid FOR UPDATE OF u`;
      if (!owners[0]) return false;
      if (!owners[0].is_active) {
        await tx.execution.updateMany({ where: { id, status: ExecutionStatus.QUEUED }, data: { status: ExecutionStatus.CANCELLED, cancellationReason: 'OWNER_SUSPENDED', finishedAt: startedAt } });
        return false;
      }
      const { count } = await tx.execution.updateMany({ where: { id, status: ExecutionStatus.QUEUED }, data: { status: ExecutionStatus.RUNNING, startedAt } });
      return count === 1;
    });
  }

  async failUnfinishedExecution(id: string, finishedAt: Date): Promise<void> {
    await this.prisma.execution.updateMany({
      where: {
        id,
        status: { in: [ExecutionStatus.QUEUED, ExecutionStatus.RUNNING] },
      },
      data: { status: ExecutionStatus.FAILED, finishedAt, errorCode: 'EXECUTION_QUEUE_FAILED' },
    });
  }

  async failStaleExecutions(startedBefore: Date): Promise<number> {
    const { count } = await this.prisma.execution.updateMany({
      where: {
        status: ExecutionStatus.RUNNING,
        triggerType: TriggerType.MANUAL,
        startedAt: { lt: startedBefore },
      },
      data: { status: ExecutionStatus.FAILED, finishedAt: new Date(), errorCode: 'EXECUTION_WORKER_INTERRUPTED' },
    });
    return count;
  }

  async findExecutionResult(id: string): Promise<unknown> {
    const row = await this.prisma.execution.findUnique({
      where: { id },
      include: { nodeLogs: { orderBy: { startedAt: 'asc' } } },
    });
    if (!row) return null;
    return {
      id: row.id,
      workflowId: row.workflowId,
      workflowVersionId: row.workflowVersionId,
      triggerType: row.triggerType as TriggerType,
      status: row.status,
      queuedAt: row.queuedAt,
      startedAt: row.startedAt,
      finishedAt: row.finishedAt,
      durationMs: row.durationMs,
      nodeLogs: row.nodeLogs.map((log) => ({
        id: log.id,
        nodeId: log.nodeId,
        nodeKey: log.nodeKey,
        status: log.status as ExecutionStatus,
        input: log.input,
        output: log.output,
        errorMessage: log.errorMessage,
        startedAt: log.startedAt,
        finishedAt: log.finishedAt,
        durationMs: log.durationMs,
      })),
    };
  }

  async findExecutionResultForOwner(
    id: string,
    ownerId: string,
  ): Promise<unknown> {
    const row = await this.prisma.execution.findFirst({
      where: { id, workflow: { is: { ownerId } } },
      include: { nodeLogs: { orderBy: { startedAt: 'asc' } } },
    });
    if (!row) return null;
    return {
      id: row.id,
      workflowId: row.workflowId,
      workflowVersionId: row.workflowVersionId,
      triggerType: row.triggerType,
      status: row.status,
      queuedAt: row.queuedAt,
      startedAt: row.startedAt,
      finishedAt: row.finishedAt,
      durationMs: row.durationMs,
      nodeLogs: row.nodeLogs.map((log) => ({
        id: log.id,
        nodeId: log.nodeId,
        nodeKey: log.nodeKey,
        status: log.status as ExecutionStatus,
        input: log.input,
        output: log.output,
        errorMessage: log.errorMessage,
        startedAt: log.startedAt,
        finishedAt: log.finishedAt,
        durationMs: log.durationMs,
      })),
    };
  }

  async listExecutionHistoryForOwner(
    query: ExecutionHistoryQuery,
  ): Promise<ExecutionHistoryPage> {
    const rows = await this.prisma.execution.findMany({
      where: {
        workflowId: query.workflowId,
        workflow: { is: { ownerId: query.ownerId } },
        ...(query.workflowVersionId
          ? { workflowVersionId: query.workflowVersionId }
          : {}),
      },
      orderBy: [{ queuedAt: 'desc' }, { id: 'desc' }],
      ...(query.cursor ? { cursor: { id: query.cursor }, skip: 1 } : {}),
      take: query.limit + 1,
      select: {
        id: true,
        workflowId: true,
        workflowVersionId: true,
        triggerType: true,
        status: true,
        queuedAt: true,
        startedAt: true,
        finishedAt: true,
        durationMs: true,
      },
    });
    const hasMore = rows.length > query.limit;
    const items: ExecutionHistoryItem[] = rows
      .slice(0, query.limit)
      .map((row) => ({
        ...row,
        triggerType: row.triggerType as TriggerType,
        status: row.status as ExecutionStatus,
      }));
    return {
      items,
      nextCursor: hasMore ? (items[items.length - 1]?.id ?? null) : null,
    };
  }
}
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { useAuthStore } from '../store/auth.store';
import { UserDropdown } from './UserDropdown';

describe('UserDropdown', () => {
  beforeEach(() => {
    useAuthStore.getState().logout();
  });

  afterEach(cleanup);

  it('renders nothing when user is not authenticated', () => {
    const { container } = render(<UserDropdown />);
    expect(container.firstChild).toBeNull();
  });

  it('renders user name, initials, and role badge when authenticated', () => {
    useAuthStore.getState().login('token', 'refresh', {
      id: '1',
      name: 'John Doe',
      email: 'john@example.com',
      role: 'CLIENT',
    });

    render(<UserDropdown />);

    expect(screen.getByText('John Doe')).toBeTruthy();
    expect(screen.getByText('JD')).toBeTruthy();
    expect(screen.getByText('Dev')).toBeTruthy();
  });

  it('opens dropdown menu and logs out when logout button is clicked', () => {
    useAuthStore.getState().login('token', 'refresh', {
      id: '1',
      name: 'Alice Admin',
      email: 'admin@example.com',
      role: 'ADMIN',
    });

    render(<UserDropdown />);

    // Initially dropdown details are hidden
    expect(screen.queryByText('Log out')).toBeNull();

    // Click trigger button
    fireEvent.click(screen.getByRole('button'));

    // Menu opens
    expect(screen.getByText('admin@example.com')).toBeTruthy();
    expect(screen.getByText('Log out')).toBeTruthy();

    // Click logout
    fireEvent.click(screen.getByRole('button', { name: 'Log out' }));

    expect(useAuthStore.getState().isAuthenticated).toBe(false);
    expect(useAuthStore.getState().user).toBeNull();
  });
});

