    const sevenDaysInSeconds = 7 * 24 * 60 * 60;
    await this.refreshTokenRepository.save(
      userId,
      refreshToken,
      sevenDaysInSeconds,
    );

    return {
      accessToken,
      refreshToken,
      user: {
        id: userId,
        email: user.email,
        name: user.name,
        role: user.role,
        isActive: user.isActive,
      },
    };
  }
