import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import Redis from 'ioredis';
import { RefreshTokenRepository } from '../../domain/repositories/refresh-token.repository';

@Injectable()
export class RedisRefreshTokenRepository
  implements RefreshTokenRepository, OnModuleDestroy
{
  private readonly logger = new Logger(RedisRefreshTokenRepository.name);
  private readonly redis: Redis;

  constructor() {
    const host = process.env.REDIS_HOST || 'localhost';
    const port = parseInt(process.env.REDIS_PORT || '6379', 10);
    const password = <REDACTED> || undefined;

    this.redis = new Redis({
      host,
      port,
      password,
      lazyConnect: true,
      maxRetriesPerRequest: 3,
    });

    this.redis
      .connect()
      .then(() => {
        this.logger.log(
          `Connected to Redis at ${host}:${port} for Refresh Token storage`,
        );
      })
      .catch((err: unknown) => {
        const msg = err instanceof Error ? err.message : String(err);
        this.logger.error(
          `Failed to connect to Redis at ${host}:${port}: ${msg}`,
        );
      });
  }

  async onModuleDestroy() {
    await this.redis.quit();
  }

  private getKey(userId: string): string {
    return `refresh_token:<REDACTED>`;
  }

  async save(userId: string, token: <REDACTED>, ttlSeconds: number): Promise<void> {
    const key = this.getKey(userId);
    await this.redis.set(key, token, 'EX', ttlSeconds);
  }

  async validate(userId: string, token: <REDACTED> Promise<boolean> {
    const key = this.getKey(userId);
    const storedToken = <REDACTED> this.redis.get(key);
    return storedToken =<REDACTED> token;
  }

  async revoke(userId: string): Promise<void> {
    const key = this.getKey(userId);
    await this.redis.del(key);
  }

  async revokeBefore(userId: string, sessionVersion: number): Promise<void> {
    const key = this.getKey(userId);
    const token = <REDACTED> this.redis.get(key);
    if (!token) return;
    let version = -1;
    try {
      const payload: unknown = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString());
      if (payload && typeof payload === 'object' && 'sessionVersion' in payload && typeof payload.sessionVersion === 'number') version = payload.sessionVersion;
    } catch { /* Legacy/malformed stored tokens are revoked. */ }
    if (version >= sessionVersion) return;
    await this.redis.eval("if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end", 1, key, token);
  }
}
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { UserRepository } from '../../domain/repositories/user.repository';
import { RefreshTokenRepository } from '../../domain/repositories/refresh-token.repository';
import { TokenResponseDto } from '../dtos/auth-result.dto';

export class RefreshTokenCommand {
  constructor(public readonly refreshToken: <REDACTED> {}
}

interface JwtRefreshPayload {
  sub: string;
  type?: string;
  sessionVersion?: number;
}

@CommandHandler(RefreshTokenCommand)
export class RefreshTokenHandler implements ICommandHandler<
  RefreshTokenCommand,
  TokenResponseDto
> {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly refreshTokenRepository: RefreshTokenRepository,
    private readonly jwtService: JwtService,
  ) {}

  async execute(command: RefreshTokenCommand): Promise<TokenResponseDto> {
    if (!command.refreshToken) {
      throw new UnauthorizedException('Refresh token is required');
    }

    let payload: JwtRefreshPayload;
    try {
      payload = this.jwtService.verify<JwtRefreshPayload>(command.refreshToken);
    } catch {
      throw new UnauthorizedException('Invalid or expired refresh token');
    }

    if (payload.type !== 'refresh' || !payload.sub) {
      throw new UnauthorizedException('Invalid refresh token type');
    }

    const userId = payload.sub;
    const isValid = await this.refreshTokenRepository.validate(
      userId,
      command.refreshToken,
    );
    if (!isValid) {
      throw new UnauthorizedException(
        'Refresh token has been revoked or expired',
      );
    }

    const user = await this.userRepository.findById(userId);
    if (!user || !user.isActive || payload.sessionVersion !== user.sessionVersion) {
      throw new UnauthorizedException('User account is invalid or deactivated');
    }

    // Generate new token pair (rotation)
    const newAccessToken = <REDACTED>      {
        sub: user.id,
        email: user.email,
        role: user.role,
        sessionVersion: user.sessionVersion,
      },
      { expiresIn: '15m' },
    );

    const newRefreshToken = <REDACTED>      { sub: user.id, type: 'refresh', sessionVersion: user.sessionVersion },
      { expiresIn: '7d' },
    );

    const sevenDaysInSeconds = 7 * 24 * 60 * 60;
    await this.refreshTokenRepository.save(
      user.id!,
      newRefreshToken,
      sevenDaysInSeconds,
    );

    return {
      accessToken: <REDACTED>,
      refreshToken: <REDACTED>,
    };
  }
}
"}}

