    },
  )
  password: <REDACTED>;

  @ApiProperty({ example: 'Alex Mercer' })
  @IsString()
  @IsNotEmpty({ message: 'Name cannot be empty' })
  name: string;

  @IsEmpty({ message: 'Role cannot be selected during registration' })
  role?: never;

  @ApiPropertyOptional({ example: '123456', minLength: 6, maxLength: 6 })
  @IsOptional()
  @IsString()
