      name: 'System User',
      role: UserRole.CLIENT,
      isActive: true,
    },
  });

  await prisma.user.upsert({
    where: { id: frontendUserId },
    update: {
      passwordHash: '$2b$10$nx.K4i7OWVN03lAln6.f3OYlf/Wg6MdAvmBY9M.1jeYyrYJoyk7FW',
      isActive: true,
    },
    create: {
