            aria-label="Close"
          >
            <X className="size-4" />
          </button>
        </div>

        {/* Tab switchers (only visible when in login or register mode) */}
        {tab !== 'forgot-password' ? (
          <div className="mt-4 grid grid-cols-2 rounded-lg bg-muted p-1 text-xs font-medium text-muted-foreground">
